pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    // fuzz the interfaceId bytes4 value
    function testFuzz_property(bytes4 interfaceId) public {
        // admissible domain: any 4-byte value is allowed (no vm.assume)
        // We will check that the reference contract always reports support for IERC165's id (0x01ffc9a7)
        // and in particular that querying that id returns true. The mutant removed ERC165 check and
        // thus would return false for that id — the fuzzer will try many interfaceId values including that one.

        // compute the well-known IERC165 interface id
        bytes4 IERC165_ID = type(IERC165Like).interfaceId;

        // call supportsInterface for the fuzzed interfaceId to ensure call completes (we only observe result)
        bool ok;
        try c.supportsInterface(interfaceId) returns (bool res) {
            ok = true; // call succeeded
            // We don't assert on this result; it's only to ensure the call path is exercised.
        } catch {
            ok = false; // if it reverts (shouldn't), record
        }

        // Now the one universal property we assert:
        // For all inputs, the reference contract must report that it supports IERC165 (interface id 0x01ffc9a7).
        // This is read via public supportsInterface; the mutant (which only returns true for IAccessControl)
        // will return false for IERC165 and thus fail this assertion for that input.
        bool supportsIERC165;
        try c.supportsInterface(IERC165_ID) returns (bool res2) {
            supportsIERC165 = res2;
        } catch {
            supportsIERC165 = false;
        }

        // Single assertion: the reference must always return true for IERC165 id; the mutant will fail for that id.
        assertTrue(supportsIERC165);
    }
}

// Minimal IERC165-like interface to obtain the interface id constant in Solidity
interface IERC165Like {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

