pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    // fuzz the interface id; the property: reference C should NOT claim support for all ids.
    function testFuzz_property(bytes4 iface) public {
        // We keep the domain wide; no tight assumptions. We only need at least one input where
        // reference returns false while mutant would return true. For the reference C, there
        // are many iface values that it does not support (most bytes4). The fuzzer will find one.

        // Call supportsInterface and capture whether it returned (did not revert) and its boolean.
        bool ok;
        bool supported;
        try c.supportsInterface(iface) returns (bool r) {
            ok = true; supported = r;
        } catch {
            // supportsInterface is view and should not revert; treat revert as not-ok
            ok = false; supported = false;
        }

        // The universal property we assert: for every iface, if the call succeeded, then
        // when the reference legitimately does NOT support the iface, supported == false.
        // The mutant that always returns true will violate this for some iface values.
        // So assert that NOT supported OR call failed. This holds for the correct contract for all iface,
        // because when it doesn't support an iface it returns false; for the mutant it will return true
        // for all iface, causing this assertion to fail for those unsupported iface values.
        assertTrue(!ok || supported == (iface == type(IERC165).interfaceId || iface == type(IAccessControl).interfaceId));
    }
}

