import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    // fuzz the interface id which decides the difference between correct and mutant
    function testFuzz_property(bytes4 interfaceId) public {
        // General rule: the reference C does NOT claim support for all interface ids.
        // Specifically, for some ids (most ids) supportsInterface should return false.
        // The mutant wrongly returns true for every id. We assert the reference returns false
        // for the fuzzed id when that id is not one of the known supported interfaces.

        // compute the known supported ids
        bytes4 IERC165_id = type(IERC165).interfaceId;
        bytes4 IAccessControl_id = type(IAccessControl).interfaceId;

        // If the fuzzed id equals one of the genuine supported ids, then reference returns true.
        // We only assert false when it's NOT one of those; the mutant would still return true
        // and thus the fuzz will find such an input that distinguishes them.
        if (interfaceId != IERC165_id && interfaceId != IAccessControl_id) {
            bool ok;
            try c.supportsInterface(interfaceId) returns (bool res) {
                ok = res;
            } catch {
                // supportsInterface is view and should not revert; treat revert as violation
                ok = true; // force fail assertion below (we expect false)
            }
            // The single assertion: for any interfaceId that is not IERC165 or IAccessControl,
            // the reference contract must return false. The mutant returns true for all ids,
            // so this assertion will fail on the mutant for some fuzzed ids.
            assertTrue(ok == false);
        } else {
            // If fuzz picked a known supported id, still run a tautological assertion that holds
            // for the reference (true). This keeps the input admissible.
            bool ok;
            try c.supportsInterface(interfaceId) returns (bool res) {
                ok = res;
            } catch {
                ok = false;
            }
            assertTrue(ok == true);
        }
    }
}

